// Do not edit this file as it will be overwritten if HAMR codegen is rerun
@msig trait SessionControl_acquisition_process_session_control_TestApi {

  def BeforeEntrypoint(): Unit = {
    Art.initTest(Arch.EITAcquisitionSupervisorSystem_Instance_acquisition_process_session_control)
  }

  def AfterEntrypoint(): Unit = {
    Art.finalizeTest(Arch.EITAcquisitionSupervisorSystem_Instance_acquisition_process_session_control)
  }

  def testCompute(): Unit = {
    Art.manuallyClearOutput()
    Art.testCompute(Arch.EITAcquisitionSupervisorSystem_Instance_acquisition_process_session_control)
  }

  def testInitialise(): Unit = {
    Art.manuallyClearOutput()
    Art.testInitialise(Arch.EITAcquisitionSupervisorSystem_Instance_acquisition_process_session_control)
  }

  /** helper function to set the values of all input ports.
   * @param request_facts payload for data port request_facts
   * @param recovery_frame payload for data port recovery_frame
   * @param start_feasibility payload for data port start_feasibility
   */
  def put_concrete_inputs(request_facts : EIT_Acquisition_Supervisor.RequestFactsRecord,
                          recovery_frame : EIT_Acquisition_Supervisor.RecoveryFrame,
                          start_feasibility : EIT_Acquisition_Supervisor.StartFeasibility.Type): Unit = {
    put_request_facts(request_facts)
    put_recovery_frame(recovery_frame)
    put_start_feasibility(start_feasibility)
  }


  /** helper function to check SessionControl_acquisition_process_session_control's
   * output ports.  Use named arguments to check subsets of the output ports.
   * @param session_frame method that will be called with the value of the outgoing data
   *        port 'session_frame'.
   */
  def check_concrete_output(session_frame: EIT_Acquisition_Supervisor.SessionFrame => B): Unit = {
    var testFailures: ISZ[ST] = ISZ()

    val session_frameValue: EIT_Acquisition_Supervisor.SessionFrame = get_session_frame().get
    if(!session_frame(session_frameValue)) {
      testFailures = testFailures :+ st"'session_frame' did not match expected: value of the outgoing data port is ${session_frameValue}"
    }

    assert(testFailures.isEmpty, st"${(testFailures, "\n")}".render)
  }


  // setter for in DataPort
  def put_request_facts(value : EIT_Acquisition_Supervisor.RequestFactsRecord): Unit = {
    Art.insertInInfrastructurePort(Arch.EITAcquisitionSupervisorSystem_Instance_acquisition_process_session_control.operational_api.request_facts_Id, EIT_Acquisition_Supervisor.RequestFactsRecord_Payload(value))
  }

  // setter for in DataPort
  def put_recovery_frame(value : EIT_Acquisition_Supervisor.RecoveryFrame): Unit = {
    Art.insertInInfrastructurePort(Arch.EITAcquisitionSupervisorSystem_Instance_acquisition_process_session_control.operational_api.recovery_frame_Id, EIT_Acquisition_Supervisor.RecoveryFrame_Payload(value))
  }

  // setter for in DataPort
  def put_start_feasibility(value : EIT_Acquisition_Supervisor.StartFeasibility.Type): Unit = {
    Art.insertInInfrastructurePort(Arch.EITAcquisitionSupervisorSystem_Instance_acquisition_process_session_control.operational_api.start_feasibility_Id, EIT_Acquisition_Supervisor.StartFeasibility_Payload(value))
  }

  // getter for out DataPort
  def get_session_frame(): Option[EIT_Acquisition_Supervisor.SessionFrame] = {
    val value: Option[EIT_Acquisition_Supervisor.SessionFrame] = get_session_frame_payload() match {
      case Some(EIT_Acquisition_Supervisor.SessionFrame_Payload(v)) => Some(v)
      case Some(v) => halt(s"Unexpected payload on port session_frame.  Expecting 'EIT_Acquisition_Supervisor.SessionFrame_Payload' but received ${v}")
      case _ => None[EIT_Acquisition_Supervisor.SessionFrame]()
    }
    return value
  }

  // payload getter for out DataPort
  def get_session_frame_payload(): Option[EIT_Acquisition_Supervisor.SessionFrame_Payload] = {
    return Art.observeOutInfrastructurePort(Arch.EITAcquisitionSupervisorSystem_Instance_acquisition_process_session_control.initialization_api.session_frame_Id).asInstanceOf[Option[EIT_Acquisition_Supervisor.SessionFrame_Payload]]
  }

}
